mapper.select:
SELECT b.*, u.nickname as author_name, u.avatar as author_avatar, c.name as category_name FROM tb_blog b LEFT JOIN tb_user u ON b.author_id = u.id LEFT JOIN tb_category c ON b.category_id = c.id WHERE b.deleted = 0
AND b.category_id = #{categoryId}
AND b.id IN (SELECT blog_id FROM tb_blog_tag WHERE tag_id = #{tagId})
AND (b.title LIKE CONCAT('%', #{keyword}, '%') OR b.summary LIKE CONCAT('%', #{keyword}, '%'))
AND b.status = #{status}
ORDER BY b.is_top DESC, b.create_time DESC
